  'Dizer que posição a gente devolve em campo': {es:'Decir que la posición se defiende en la cancha', en:'Say we prove our spot on the pitch'},
  'Reconhecer a {nome} na frente': {es:'Reconocer a {nome} adelante', en:'Acknowledge {nome} are ahead'},
  'reconheceu quem está na frente': {es:'reconoció a quien va adelante', en:"acknowledged who's ahead"},

