  'Deixamos quieto. Nada mudou.': {es:'Lo dejamos quieto. Nada cambió.', en:'We left it alone. Nothing changed.'},
  'Peitou a cidade': {es:'Se le plantó a la ciudad', en:'Stood up to the town'},
  '+{n} de moral': {es:'+{n} de moral', en:'+{n} morale'},
  'Inauguração com a cidade toda': {es:'Inauguración con toda la ciudad', en:'Opening with the whole town'},
  '+{n} de relação com o clube': {es:'+{n} de relación con el club', en:'+{n} relationship with the club'},
  '{n} com a {nome}': {es:'{n} con la {nome}', en:'{n} with {nome}'},
  '{d} com {n} rival': {es:'{d} con {n} rival', en:'{d} with {n} rival'},
