  'TERMINAL': {es:'TERMINAL', en:'STATION'},
  'fechado: pega o bonde na descida, a PM chega rápido': {es:'cerrado: agarra a la banda al bajar, la policía llega rápido', en:'enclosed: catches the crew getting off, the police arrive fast'},
