/* aplica por cima da fonte: dia e mês entram na ficha do time; o ano
   segue o de times.js. Clube fora da lista fica no hash de sempre. */
(function(){
  const F = TO.dados.fundacoes;
  for(const t of (TO.dados.times || [])){
    const f = F[t.id];
    if(f){ t.fundacaoDia = f[0]; t.fundacaoMes = f[1]; }
  }
})();

;

